 Ultra gyors magyar kereső webapp Replitre (Flask + Exa AI + Cerebras GPTOSS120B)

Az alábbi megoldás egy minimalista, kétfájlos (main.py és index.html) Flask alkalmazás Replitre, amely:
 Magyar nyelvű felületet ad[1].
 A felhasználói magyar lekérdezést a háttérben a Cerebras GPTOSS120Bvel angolra fordítja és Exakereséshez optimalizálja[2][3][4].
 Automatikusan választ keresési módot (neural/keyword/auto) Exa APIval[5][6][7].
 Exa angolul keres, az eredményeket a GPTOSS120B magyarra fordítja és tömör választ ad vissza[5][6][2].

Megjegyzések:
 Exa API: szükséges EXA_API_KEY környezeti változó[5][6][8].
 Cerebras GPTOSS120B: OpenAIféle GPTOSS120B nyílt súlyú modell elérhető szolgáltatókon (pl. Cerebras Cloud kompatibilis OpenAIszerű APIval), a kódban OPENAI_API_KEY változóval használjuk az OpenAIkompatibilis endpointot[2][4][3].
 Repliten a Flask gyorsan futtatható main.pyvel[1][9][10].

Helyettesítendő környezeti változók Replitben (Secrets):
 EXA_API_KEY
 OPENAI_API_KEY


main.py

python
import os
import json
import time
from flask import Flask, request, render_template, jsonify
import requests

# Beállítások
EXA_API_KEY = os.getenv("EXA_API_KEY", "")
OPENAI_API_KEY = os.getenv("OPENAI_API_KEY", "")

# OpenAI-kompatibilis endpoint (Cerebras Cloud OpenAI kompatibilis interfész)
# Ha saját szolgáltatót használsz (OpenRouter/Fireworks/Cerebras), állítsd át az alábbi BASE_URL-t a szolgáltató OpenAI-kompatibilis URL-jére.
BASE_URL = os.getenv("OPENAI_BASE_URL", "https://api.openai.com/v1")
MODEL_NAME = os.getenv("LLM_MODEL", "gpt-oss-120b")  # GPT-OSS-120B modellnév[23]

# Exa API
EXA_SEARCH_URL = "https://api.exa.ai/search"
EXA_CONTENTS_URL = "https://api.exa.ai/contents"

app = Flask(__name__)

def openai_chat(messages, temperature=0.2, max_tokens=800, response_format=None):
    """
    OpenAI-kompatibilis Chat Completions hívás GPT-OSS-120B-hez (pl. Cerebras/OpenRouter/Fireworks).
    """
    headers = {
        "Authorization": f"Bearer {OPENAI_API_KEY}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": MODEL_NAME,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    if response_format:
        payload["response_format"] = response_format
    r = requests.post(f"{BASE_URL}/chat/completions", headers=headers, json=payload, timeout=30)
    r.raise_for_status()
    data = r.json()
    return data["choices"][0]["message"]["content"]

def exa_search(query_en, mode="auto", num_results=5):
    """
    Exa keresés neural/keyword/auto módban[10][9][16].
    """
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {
        "query": query_en,
        "num_results": num_results,
        "type": mode  # "auto" intelligensen választ a Exa[10][9][16]
    }
    r = requests.post(EXA_SEARCH_URL, headers=headers, json=body, timeout=30)
    r.raise_for_status()
    return r.json()

def exa_contents(ids):
    """
    Letisztított tartalom lekérése a találatokhoz[10].
    """
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {"ids": ids}
    r = requests.post(EXA_CONTENTS_URL, headers=headers, json=body, timeout=30)
    r.raise_for_status()
    return r.json()

def pick_search_mode(user_intent_hu):
    """
    Keresési mód kiválasztása a felhasználói igény alapján (a háttérben, láthatatlanul).
    A döntést a GPT-OSS-120B végzi ultra rövid JSON-ban.
    """
    sys = (
        "Dönts Exa keresési módot. Válasz kizárólag ilyen JSON legyen: "
        '{"mode":"auto|neural|keyword","results":5}\n'
        "Irányelv: precíz kulcsszavas kifejezések -> keyword; homályos/összetett kutatás -> neural; egyéb -> auto."
    )
    user = f"Felhasználói szándék (HU): {user_intent_hu}\nAdj 5-8 találatot általában."
    content = openai_chat(
        [{"role": "system", "content": sys}, {"role": "user", "content": user}],
        temperature=0.0,
        max_tokens=50
    )
    try:
        data = json.loads(content.strip())
        mode = data.get("mode", "auto")
        results = int(data.get("results", 6))
        results = max(3, min(results, 10))
        if mode not in ["auto", "neural", "keyword"]:
            mode = "auto"
        return mode, results
    except Exception:
        return "auto", 6

def translate_to_exa_english(hungarian_query):
    """
    HU -> EN fordítás és Exa-optimált lekérdezés generálása (kulcsszavak, frázisok, kiegészítők minimalizálása)[10][9][16].
    """
    sys = (
        "Feladat: Fordítsd a magyar keresést természetes angolra és optimalizáld Exa számára. "
        "Légy tömör, informatív; kerüld a felesleges szavakat; használd a témához illő kulcsfogalmakat."
        " Adj vissza kizárólag a végső angol lekérdezést plain textben, formázás nélkül."
    )
    user = f"Magyar keresés: {hungarian_query}"
    return openai_chat(
        [{"role": "system", "content": sys}, {"role": "user", "content": user}],
        temperature=0.2,
        max_tokens=120
    ).strip()

def synthesize_hu_answer(query_hu, search_query_en, results, contents):
    """
    Eredmények magyar nyelvű tömörítése és visszaadása a felhasználónak.
    A felhasználó csak magyar választ lát.
    """
    sys = (
        "Feladat: Foglald össze tömören és magyarul a megadott angol találatok tartalmát. "
        "Adj lényegi választ, lista csak ha indokolt. Kerüld az angol szavakat, ne említs háttérfolyamatokat."
    )
    context = {
        "query_hu": query_hu,
        "search_query_en": search_query_en,
        "results_meta": results,
        "contents": contents
    }
    user = json.dumps(context, ensure_ascii=False)
    return openai_chat(
        [{"role": "system", "content": sys}, {"role": "user", "content": user}],
        temperature=0.2,
        max_tokens=800
    ).strip()

@app.route("/", methods=["GET"])
def home():
    return render_template("index.html")

@app.route("/search", methods=["POST"])
def search():
    t0 = time.time()
    data = request.get_json(silent=True) or {}
    q_hu = (data.get("q") or "").strip()
    if not q_hu:
        return jsonify({"error": "Üres lekérdezés."}), 400

    # 1) Keresési mód kiválasztása (láthatatlanul)
    mode, num_results = pick_search_mode(q_hu)

    # 2) HU -> EN + Exa-optimalizált
    q_en = translate_to_exa_english(q_hu)

    # 3) Exa keresés
    search_json = exa_search(q_en, mode=mode, num_results=num_results)

    # 4) Tartalom lekérés (ha van id)
    ids = [item.get("id") for item in (search_json.get("results") or []) if item.get("id")]
    contents_json = {"results": []}
    if ids:
        contents_json = exa_contents(ids)

    # 5) Magyar tömör válasz
    answer_hu = synthesize_hu_answer(q_hu, q_en, search_json, contents_json)

    elapsed_ms = int((time.time() - t0) * 1000)
    return jsonify({
        "ok": True,
        "elapsed_ms": elapsed_ms,
        "answer_hu": answer_hu
    })

if __name__ == "__main__":
    # Replit ajánlott futtatás[24]
    app.run(host="0.0.0.0", port=8000, debug=False)



