python
import os
import json
import time
from flask import Flask, request, render_template, jsonify
from urllib import request as urlreq
from urllib.error import HTTPError, URLError

# Kötelező titkok (Replit Secrets)
EXA_API_KEY = os.getenv("EXA_API_KEY")  # Exa API kulcs
LLM_API_KEY = os.getenv("LLM_API_KEY")  # OpenAI-kompatibilis kulcs a GPT-OSS-120B-hez

# OpenAI-kompatibilis Chat Completions végpont (állítható, de NEM placeholder)
LLM_BASE_URL = os.getenv("LLM_BASE_URL", "https://api.openai.com/v1")
LLM_MODEL = os.getenv("LLM_MODEL", "gpt-oss-120b")

# Exa végpontok
EXA_SEARCH_URL = "https://api.exa.ai/search"
EXA_CONTENTS_URL = "https://api.exa.ai/contents"

TIMEOUT = 25  # alacsony timeout a gyors válaszért
app = Flask(__name__)

def http_json_post(url, headers, body_obj, timeout=TIMEOUT):
    data = json.dumps(body_obj).encode("utf-8")
    req = urlreq.Request(url, data=data, headers=headers, method="POST")
    with urlreq.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
        return json.loads(raw.decode("utf-8"))

def llm_chat(messages, temperature=0.2, max_tokens=700):
    if not LLM_API_KEY:
        raise RuntimeError("Hiányzó LLM_API_KEY titok.")
    headers = {
        "Authorization": f"Bearer {LLM_API_KEY}",
        "Content-Type": "application/json",
    }
    payload = {
        "model": LLM_MODEL,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    resp = http_json_post(f"{LLM_BASE_URL}/chat/completions", headers, payload)
    # OpenAI-kompatibilis válasz
    return resp["choices"][0]["message"]["content"].strip()

def exa_search(query_en, mode="auto", num_results=6):
    if not EXA_API_KEY:
        raise RuntimeError("Hiányzó EXA_API_KEY titok.")
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {"query": query_en, "num_results": num_results, "type": mode}
    return http_json_post(EXA_SEARCH_URL, headers, body)

def exa_contents(ids):
    if not EXA_API_KEY:
        raise RuntimeError("Hiányzó EXA_API_KEY titok.")
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {"ids": ids}
    return http_json_post(EXA_CONTENTS_URL, headers, body)

def pick_search_mode(user_intent_hu):
    sys = (
        "Válaszd ki az Exa keresési módját és a találatok számát rövid JSON-ban: "
        '{"mode":"auto|neural|keyword","results":5..10}. '
        "Kulcsszavas, pontos igény -> keyword; tág/kutató -> neural; egyéb -> auto."
    )
    out = llm_chat(
        [{"role": "system", "content": sys},
         {"role": "user", "content": user_intent_hu}],
        temperature=0.0,
        max_tokens=50
    )
    try:
        data = json.loads(out)
        mode = data.get("mode", "auto")
        if mode not in ("auto", "neural", "keyword"):
            mode = "auto"
        results = int(data.get("results", 6))
        results = max(3, min(results, 10))
        return mode, results
    except Exception:
        return "auto", 6

def translate_hu_to_exa_en(hq):
    sys = (
        "Fordítsd a magyar keresést természetes angolra és optimalizáld Exa kereséshez."
        " Legyen tömör, informatív, felesleges szavak nélkül; csak a végső lekérdezést add vissza."
    )
    return llm_chat(
        [{"role": "system", "content": sys},
         {"role": "user", "content": hq}],
        temperature=0.2,
        max_tokens=120
    )

def synthesize_answer_hu(query_hu, query_en, results, contents):
    sys = (
        "Foglalj össze magyarul tömören a megadott angol találatok alapján."
        " Adj lényegi választ; lista csak ha indokolt; ne említsd a háttérfolyamatokat."
    )
    ctx = {"query_hu": query_hu, "query_en": query_en,
           "results": results, "contents": contents}
    return llm_chat(
        [{"role": "system", "content": sys},
         {"role": "user", "content": json.dumps(ctx, ensure_ascii=False)}],
        temperature=0.2,
        max_tokens=800
    )

@app.route("/", methods=["GET"])
def home():
    return render_template("index.html")

@app.route("/search", methods=["POST"])
def search():
    t0 = time.time()
    data = request.get_json(silent=True) or {}
    q_hu = (data.get("q") or "").strip()
    if not q_hu:
        return jsonify({"error": "Üres lekérdezés."}), 400
    try:
        mode, k = pick_search_mode(q_hu)
        q_en = translate_hu_to_exa_en(q_hu)
        s = exa_search(q_en, mode=mode, num_results=k)
        ids = [r.get("id") for r in (s.get("results") or []) if r.get("id")]
        c = exa_contents(ids) if ids else {"results": []}
        ans = synthesize_answer_hu(q_hu, q_en, s, c)
        return jsonify({"ok": True, "elapsed_ms": int((time.time()-t0)*1000), "answer_hu": ans})
    except (HTTPError, URLError) as e:
        return jsonify({"error": f"Hálózati hiba: {e}"}), 502
    except Exception as e:
        return jsonify({"error": f"Hiba: {e}"}), 500

if __name__ == "__main__":
    # Replit: a 8000-es port ajánlott
    app.run(host="0.0.0.0", port=8000, debug=False)


