TIMEOUT = 25

app = Flask(__name__)
INDEX_HTML = Path(__file__).with_name("index.html").read_text(encoding="utf-8")

def http_json_post(url, headers, body_obj, timeout=TIMEOUT):
    data = json.dumps(body_obj, ensure_ascii=False).encode("utf-8")
    req = ureq.Request(url, data=data, headers=headers, method="POST")
    with ureq.urlopen(req, timeout=timeout) as resp:
        raw = resp.read()
        return json.loads(raw.decode("utf-8"))

def llm_chat(messages, temperature=0.2, max_tokens=700):
    if not LLM_API_KEY:
        raise RuntimeError("Hiányzó LLM_API_KEY")
    headers = {"Authorization": f"Bearer {LLM_API_KEY}", "Content-Type": "application/json"}
    payload = {"model": LLM_MODEL, "messages": messages, "temperature": temperature, "max_tokens": max_tokens}
    resp = http_json_post(f"{LLM_BASE_URL}/chat/completions", headers, payload)
    return resp["choices"][0]["message"]["content"].strip()

def exa_search(query_en, mode="auto", num_results=6):
    if not EXA_API_KEY:
        raise RuntimeError("Hiányzó EXA_API_KEY")
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {"query": query_en, "numResults": num_results, "type": mode}
    return http_json_post(EXA_SEARCH_URL, headers, body)

def exa_contents(ids):
    headers = {"Content-Type": "application/json", "x-api-key": EXA_API_KEY}
    body = {"ids": ids}
    return http_json_post(EXA_CONTENTS_URL, headers, body)

def pick_search_mode(user_intent_hu):
    sys = 'Válaszd ki az Exa keresési módját és találatok számát rövid JSON-ban: {"mode":"auto|neural|keyword","results":5..10}. Kulcsszavas, pontos igény -> keyword; tág/kutató -> neural; egyéb -> auto.'
    out = llm_chat([{"role": "system", "content": sys}, {"role": "user", "content": user_intent_hu}], temperature=0.0, max_tokens=50)
    try:
        data = json.loads(out)
        mode = data.get("mode", "auto")
        if mode not in ("auto", "neural", "keyword"):
            mode = "auto"
        results = int(data.get("results", 6))
        results = max(3, min(results, 10))
        return mode, results
    except Exception:
        return "auto", 6

def translate_hu_to_exa_en(hq):
    sys = "Fordítsd a magyar keresést természetes angolra és optimalizáld Exa kereséshez. Legyen tömör, informatív, felesleges szavak nélkül; csak a végső lekérdezést add vissza."
    return llm_chat([{"role": "system", "content": sys}, {"role": "user", "content": hq}], temperature=0.2, max_tokens=120)

def synthesize_answer_hu(query_hu, query_en, results, contents):
    sys = "Foglalj össze magyarul tömören a megadott angol találatok alapján. Adj lényegi választ; lista csak ha indokolt; ne említsd a háttérfolyamatokat."
    ctx = {"query_hu": query_hu, "query_en": query_en, "results": results, "contents": contents}
    return llm_chat([{"role": "system", "content": sys}, {"role": "user", "content": json.dumps(ctx, ensure_ascii=False)}], temperature=0.2, max_tokens=800)

@app.route("/", methods=["GET"])
def home():
    return Response(INDEX_HTML, mimetype="text/html; charset=utf-8")

@app.route("/search", methods=["POST"])
def search():
    t0 = time.time()
    data = request.get_json(silent=True) or {}
    q_hu = (data.get("q") or "").strip()
    if not q_hu:
        return jsonify({"error": "Üres lekérdezés."}), 400
    try:
        mode, k = pick_search_mode(q_hu)
        q_en = translate_hu_to_exa_en(q_hu)
        s = exa_search(q_en, mode=mode, num_results=k)
        ids = [r.get("id") for r in (s.get("results") or []) if isinstance(r, dict) and r.get("id")]
        c = exa_contents(ids) if ids else {"results": []}
        ans = synthesize_answer_hu(q_hu, q_en, s, c)
        return jsonify({"ok": True, "elapsed_ms": int((time.time() - t0) * 1000), "answer_hu": ans})
    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    port = int(os.getenv("PORT", "8000"))
    app.run(host="0.0.0.0", port=port, debug=False, threaded=True)


