<!doctype html>
<html lang="hu">
<head>
<meta charset="utf-8">
<title>Villámgyors magyar kereső</title>
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
:root { color-scheme: light dark; }
body { font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; margin: 0; }
header { padding: 16px; text-align: center; }
h1 { margin: 8px 0 0; font-size: 20px; }
.container { max-width: 820px; margin: 0 auto; padding: 16px; }
.row { display: flex; gap: 8px; }
input[type="text"] { flex: 1; padding: 12px 14px; font-size: 16px; border-radius: 10px; border: 1px solid #bbb; outline: none; }
button { padding: 12px 16px; font-size: 16px; border-radius: 10px; border: 1px solid #888; cursor: pointer; }
.result { margin-top: 18px; white-space: pre-wrap; line-height: 1.5; }
.muted { color: gray; font-size: 12px; margin-top: 6px; }
.spinner { display: inline-block; width: 18px; height: 18px; border: 2px solid #ccc; border-top-color: #333; border-radius: 50%; animation: spin .8s linear infinite; vertical-align: middle; }
@keyframes spin { to { transform: rotate(360deg);} }
</style>
</head>
<body>
<header><h1>Villámgyors magyar kereső</h1></header>
<div class="container">
<div class="row">
<input id="q" type="text" placeholder="Mit keresel?" autofocus>
<button id="go">Keresés</button>
</div>
<div id="status" class="muted"></div>
<div id="out" class="result"></div>
</div>
<script>
const q = document.getElementById('q');
const go = document.getElementById('go');
const out = document.getElementById('out');
const statusEl = document.getElementById('status');
async function runSearch() {
  const text = q.value.trim();
  if (!text) { out.textContent = "Kérlek, írj be valamit a kereséshez."; return; }
  out.textContent = "";
  statusEl.innerHTML = '<span class="spinner"></span> Keresek...';
  go.disabled = true;
  try {
    const res = await fetch('/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ q: text }) });
    const data = await res.json();
    if (!res.ok || !data.ok) { out.textContent = data.error || 'Hiba történt. Próbáld újra.'; }
    else { out.textContent = data.answer_hu || 'Nincs válasz.'; statusEl.textContent = `Kész: ${data.elapsed_ms} ms`; }
  } catch (e) {
    out.textContent = 'Hálózati hiba. Próbáld újra.';
  } finally {
    go.disabled = false;
    setTimeout(()=>{ statusEl.textContent=""; }, 2500);
  }
}
go.addEventListener('click', runSearch);
q.addEventListener('keydown', (e)=>{ if (e.key==='Enter') runSearch(); });
</script>
</body>
</html>
